cd hypothesis-python && python3.10 -c "
from typing import Optional, Union
from dataclasses import dataclass
from hypothesis import strategies as st

@dataclass
class A:
    x: str | None

@dataclass
class B:
    x: Union[str, None]

@dataclass
class C:
    x: Optional[str]

print('Testing A (str | None):')
try:
    result = st.from_type(A).example()
    print('Success:', result)
except Exception as e:
    print('Error:', e)

print('Testing B (Union[str, None]):')
try:
    result = st.from_type(B).example()
    print('Success:', result)
except Exception as e:
    print('Error:', e)

print('Testing C (Optional[str]):')
try:
    result = st.from_type(C).example()
    print('Success:', result)
except Exception as e:
    print('Error:', e)
"
